/**
 * A vector as an ImageVector of [size] on its longer side: draw it with Icon(…, tint = …) or
 * Image; its shapes are black and the tint colours them, like the site's currentColor.
 */
fun NDVector.toImageVector(name: String, size: Dp = 24.dp): ImageVector {
    val scale = size.value / maxOf(width, height)
    return ImageVector.Builder(
        name = name,
        defaultWidth = (width * scale).dp,
        defaultHeight = (height * scale).dp,
        viewportWidth = width,
        viewportHeight = height,
    ).apply {
        group(translationX = -minX, translationY = -minY) {
            for (shape in shapes) {
                addPath(
                    pathData = addPathNodes(shape.pathData),
                    pathFillType = if (shape.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = if (shape.fill) SolidColor(Color.Black) else null,
                    stroke = if (shape.stroke) SolidColor(Color.Black) else null,
                    strokeLineWidth = shape.strokeWidth,
                    strokeLineCap = when (shape.lineCap) {
                        NDLineCap.Butt -> StrokeCap.Butt
                        NDLineCap.Round -> StrokeCap.Round
                        NDLineCap.Square -> StrokeCap.Square
                    },
                    strokeLineJoin = when (shape.lineJoin) {
                        NDLineJoin.Miter -> StrokeJoin.Miter
                        NDLineJoin.Round -> StrokeJoin.Round
                        NDLineJoin.Bevel -> StrokeJoin.Bevel
                    },
                )
            }
        }
    }.build()
}

