/** A corner of [radius] dp; the pill radius becomes a fully rounded end. */
private fun ndCorner(radius: Float): CornerBasedShape =
    if (radius >= 9999f) RoundedCornerShape(percent = 50) else RoundedCornerShape(radius.dp)

